(function () {
  function _boolean_from_string(v) {
    if (typeof v === "boolean") {
      return v;
    }
    if (typeof v === "string") {
      const trimmed = v.trim();
      if (trimmed === "true" || trimmed === "_true") {
        return true;
      }
      if (trimmed === "false" || trimmed === "_false") {
        return false;
      }
    }
    throw new Error("expected boolean");
  }

  function _boolean_to_string(v) {
    return _boolean_from_string(v) ? "true" : "false";
  }

  return { _boolean_from_string, _boolean_to_string };
})
